using System.Text.Json;using CustomCodeFramework.Messaging.Outbox;using CustomCodeFramework.Messaging.Outbox.Processing;using CustomCodeFramework.Redis.Streams.Abstractions;using CustomCodeFramework.Redis.Streams.Messages;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Worker.Outbox;
internal sealed class OutboxProcessor(ServiceDbContext db,IRedisStreamPublisher publisher,IConfiguration configuration,ILogger<OutboxProcessor> logger):IOutboxProcessor{public async Task<OutboxProcessingResult> ProcessAsync(int batchSize,CancellationToken ct=default){var messages=await db.OutboxMessages.Where(x=>x.Status==OutboxMessageStatus.Pending).OrderBy(x=>x.CreatedAtUtc).Take(batchSize).ToListAsync(ct);if(messages.Count==0)return OutboxProcessingResult.Empty;var processed=0;var failed=0;foreach(var message in messages){try{var payload=JsonSerializer.Deserialize<object>(message.PayloadJson);await publisher.PublishAsync(new RedisStreamMessage{StreamName=ResolveStreamName(message.EventName),MessageType=message.EventName,Payload=payload??message.PayloadJson,Headers=CreateHeaders(message)},ct);message.Status=OutboxMessageStatus.Processed;message.ProcessedAtUtc=DateTime.UtcNow;message.ErrorMessage=null;processed++;}catch(Exception ex){message.RetryCount++;message.Status=OutboxMessageStatus.Failed;message.ErrorMessage=ex.Message;failed++;logger.LogError(ex,"Failed to publish Content outbox event {EventId} ({EventName}).",message.EventId,message.EventName);}}await db.SaveChangesAsync(ct);var more=await db.OutboxMessages.AnyAsync(x=>x.Status==OutboxMessageStatus.Pending,ct);return new OutboxProcessingResult(processed,failed,more);}private string ResolveStreamName(string eventName)=>configuration[$"Redis:Streams:Destinations:{eventName}"]??configuration["Redis:Streams:DefaultStreamName"]??"dhole.content.events";private static Dictionary<string,string>CreateHeaders(OutboxMessage m){var h=new Dictionary<string,string>{{"event_id",m.EventId.ToString()},{"event_type",m.EventType},{"event_name",m.EventName},{"source_service",m.SourceService},{"created_at_utc",m.CreatedAtUtc.ToString("O")}};if(!string.IsNullOrWhiteSpace(m.CorrelationId))h["correlation_id"]=m.CorrelationId;return h;}}
